function getAudioContext(){if(!audioContext){const Context=window.AudioContext||window.webkitAudioContext;if(Context)audioContext=new Context()}return audioContext}
function synthTone(frequency,delay,duration,type='sine',volume=.025){const context=getAudioContext();if(!context||!systemSoundsEnabled||!audioUnlocked||systemVolume<=0)return;const oscillator=context.createOscillator(),gain=context.createGain(),start=context.currentTime+delay;oscillator.type=type;oscillator.frequency.setValueAtTime(frequency,start);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,volume*systemVolume),start+.012);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(start);oscillator.stop(start+duration+.02)}
function playSystemSound(kind='notify'){if(!systemSoundsEnabled||!audioUnlocked)return;getAudioContext()?.resume?.();const patterns={startup:[[392,0,.32,'sine',.022],[523,.09,.34,'sine',.022],[659,.18,.38,'sine',.02],[784,.29,.48,'sine',.018]],open:[[660,0,.07,'triangle',.018],[880,.06,.08,'triangle',.014]],close:[[560,0,.07,'triangle',.014],[360,.055,.09,'triangle',.012]],notify:[[740,0,.09,'sine',.024],[988,.08,.14,'sine',.02]],question:[[440,0,.1,'sine',.023],[660,.12,.13,'sine',.021]],error:[[190,0,.13,'sawtooth',.028],[145,.13,.18,'sawtooth',.024]],game:[[523,0,.07,'square',.015],[659,.07,.07,'square',.014],[784,.14,.11,'square',.013]],shutdown:[[660,0,.18,'sine',.02],[523,.12,.22,'sine',.018],[392,.25,.32,'sine',.016]]};(patterns[kind]||patterns.notify).forEach(tone=>synthTone(...tone))}
function unlockSystemAudio(playStartup=true){if(audioUnlocked)return;audioUnlocked=true;getAudioContext()?.resume?.();if(playStartup&&systemSoundsEnabled&&!startupSoundPlayed){startupSoundPlayed=true;playSystemSound('startup')}}
