const explorerTools=[['back','后退','back'],['forward','前进','forward'],['up','向上','up'],['separator'],['search','搜索','search'],['folders','文件夹','folder'],['separator'],['cut','剪切','cut'],['copy','复制','copy'],['paste','粘贴','paste'],['delete','删除','delete'],['separator'],['refresh','刷新','refresh'],['views','查看','views']];
function ensureExplorerAddress(win,path){let address=win.querySelector('.addressbar');if(address)return address;address=document.createElement('div');address.className='addressbar shell-addressbar';address.innerHTML='<span>地址</span><div class="w2k-address folder-address"></div>';address.querySelector('div').textContent=path;const anchor=win.querySelector('.gallery-toolbar,.window-body');win.insertBefore(address,anchor);return address}
function runExplorerAction(app,win,action){const location=explorerLocations[app],selected=shellSelection(win),container=shellContainerFor(win);if(action==='up'&&app==='documents'&&documentsDirectoryStack.length>1)goUpDocumentsDirectory();else if(action==='up'&&location.parent)openApp(location.parent);else if(action==='search')showIEPage('搜索',`<p>在 YFGeek 桌面中搜索文件和网页。</p><form action="https://www.google.com/search"><input name="q" value="YFGeek"><button>搜索</button></form>`);else if(action==='folders')win.classList.toggle('explorer-folders-hidden');else if(action==='cut')copyShellItem(selected,'cut');else if(action==='copy')copyShellItem(selected);else if(action==='paste')pasteShellItems(container);else if(action==='delete')deleteShellItem(selected);else if(action==='refresh'){if(app==='documents')refreshDocumentsDirectory();else win.querySelector('.window-body')?.animate([{opacity:.55},{opacity:1}],{duration:140})}else if(action==='views')container?.classList.toggle('compact-view')}
function registerExplorerWindow(app,location){const win=getWindow(app);if(!win)return;const address=ensureExplorerAddress(win,location.path),bar=document.createElement('div');bar.className='explorer-toolbar';bar.setAttribute('aria-label','资源管理器工具栏');explorerTools.forEach(([action,label,role])=>{if(action==='separator'){bar.appendChild(document.createElement('i'));return}const button=document.createElement('button'),image=setSystemImage(document.createElement('img'),role);button.type='button';button.dataset.explorerAction=action;button.title=label;button.setAttribute('aria-label',label);image.alt='';button.append(image,Object.assign(document.createElement('span'),{textContent:label}));if(action==='refresh'&&app==='documents')button.id='documentsRefresh';if(['back','forward','cut','copy','paste','delete'].includes(action)||(action==='up'&&!location.parent))button.disabled=true;button.addEventListener('click',()=>runExplorerAction(app,win,action));bar.appendChild(button)});address.before(bar);refreshExplorerCommands(win)}
