// Some touch browsers finish a tap at pointerup without synthesizing click.
// Dialog actions get a touch-only fallback while suppressing the duplicate click.
addEventListener('pointerup',event=>{if(!isMobileOrTablet())return;const button=event.target.closest('.dialog-actions button,.dialog-actions a');if(!button||button.disabled)return;const now=Date.now();if(Number(button.dataset.touchActivated)>now-500)return;button.dataset.touchActivated=String(now);button.dataset.touchDispatching='true';button.click();delete button.dataset.touchDispatching},{capture:true});
