function arrangeDesktop(){const grid=$('.desktop-icons'),icons=$$('.desktop-icon');if(isMobileOrTablet()){const resolution=Number(document.body.dataset.resolution||2),columns=resolution===0?2:resolution===3?4:innerWidth<360?2:3,rows=Math.ceil(icons.length/columns);grid.removeAttribute('style');grid.style.setProperty('--desktop-mobile-columns',String(columns));grid.style.setProperty('--desktop-mobile-rows',String(rows));icons.forEach(i=>{i.style.removeProperty('position');i.style.removeProperty('left');i.style.removeProperty('top')});return}const available=$('#desktop').clientHeight-20,rows=Math.max(4,Math.floor(available/78)),columns=Math.ceil(icons.length/rows);grid.style.display='block';grid.style.width=`${columns*92}px`;grid.style.height=`${rows*78}px`;icons.forEach((icon,index)=>{icon.style.position='absolute';icon.style.left=`${Math.floor(index/rows)*92}px`;icon.style.top=`${(index%rows)*78}px`})}
