function closeSystemMenu(){$$('.app-menubar button.menu-open').forEach(button=>{button.classList.remove('menu-open');button.setAttribute('aria-expanded','false')});hideTransientMenu(menuPopup)}
function runMenuCommand(command){closeSystemMenu();playSystemSound('open');command.action?.()}
function renderApplicationMenu(commands){menuPopup.replaceChildren();commands.forEach(command=>{if(command.separator){const divider=document.createElement('hr');divider.setAttribute('role','separator');menuPopup.appendChild(divider);return}const button=document.createElement('button'),label=document.createElement('span'),shortcut=document.createElement('kbd');button.type='button';button.setAttribute('role','menuitem');label.textContent=command.label;shortcut.textContent=command.shortcut||'';button.append(label,shortcut);const recentTouch=bindTouchTap(button,()=>runMenuCommand(command));button.addEventListener('click',event=>{event.stopPropagation();if(recentTouch()){event.preventDefault();return}runMenuCommand(command)});menuPopup.appendChild(button)})}
function menuKeyFor(button){if(button.dataset.menu)return button.dataset.menu;const label=button.textContent.split('(')[0].trim();return menuKeys[label]||'arrange'}
function toggleApplicationMenu(button){const win=button.closest('.window'),alreadyOpen=button.classList.contains('menu-open'),provider=applicationMenus[menuKeyFor(button)];closeSystemMenu();if(alreadyOpen||!win||!provider)return;const commands=provider({app:win.dataset.app,win}).filter(Boolean);if(!commands.length)return;renderApplicationMenu(commands);const rect=button.getBoundingClientRect();menuPopup.style.left=Math.max(4,rect.left)+'px';menuPopup.style.top=rect.bottom+'px';showTransientMenu(menuPopup);const popupRect=menuPopup.getBoundingClientRect();menuPopup.style.left=Math.max(4,Math.min(rect.left,innerWidth-popupRect.width-8))+'px';if(popupRect.bottom>innerHeight-8)menuPopup.style.top=Math.max(4,innerHeight-popupRect.height-8)+'px';button.classList.add('menu-open');button.setAttribute('aria-expanded','true')}
function bindApplicationMenuBar(bar){bar.classList.add('app-menubar');bar.setAttribute('role','menubar');bar.querySelectorAll('button').forEach(button=>{button.type='button';button.setAttribute('role','menuitem');if(button.dataset.dosMode){const activate=()=>{closeSystemMenu();setDosMode(button.dataset.dosMode)},recentTouch=bindTouchTap(button,activate);button.addEventListener('click',event=>{event.stopPropagation();if(recentTouch()){event.preventDefault();return}activate()});return}button.dataset.menu=menuKeyFor(button);button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-expanded','false');const recentTouch=bindTouchTap(button,()=>toggleApplicationMenu(button));button.addEventListener('click',event=>{event.stopPropagation();if(recentTouch()){event.preventDefault();return}toggleApplicationMenu(button)})})}
$$('.menubar').forEach(bindApplicationMenuBar);
addEventListener('pointerdown',e=>{if(!e.target.closest('.system-menu,.menubar'))closeSystemMenu()});
addEventListener('keydown',e=>{if(e.key==='Escape')closeSystemMenu();if(e.altKey&&e.key.toLowerCase()==='f'){const win=$('.window.active-window:not(.hidden)'),button=win?.querySelector('.menubar button');if(button){e.preventDefault();button.click()}}});

// Display Properties
const wallpaperPreviews={
  blue:{image:'none',color:'#3a6ea5'},
  travel:{image:'url("assets/travel.jpg")',color:'#3a6ea5'},
  portrait:{image:'url("assets/me.jpg")',color:'#00164d'},
  code:{image:'url("assets/code.jpg")',color:'#101820'},
  raspberry:{image:'url("assets/raspberry.png")',color:'#dce8ef'},
  food:{image:'url("assets/food.jpg")',color:'#202020'},
  classic:{image:'none',color:'#008080'},
  midnight:{image:'radial-gradient(circle,#fff 0 1px,#00164d 2px)',color:'#00164d'}
};
const wallpaperNames=Object.keys(wallpaperPreviews);
let pendingWallpaper='blue';
const shellThemes=['win98','win2000','winxp'];
const shellThemeDetails={
  win98:{version:'98',edition:'Second Edition',name:'YFGeek 98',tagline:'YFGeek Desktop',color:'#008080',bootVendor:'',bootProduct:'YFGeek 98',bootBadge:'',bootTagline:'Second Edition'},
  win2000:{version:'2000',edition:'Professional',name:'YFGeek 2000',tagline:'Built for YFGeek',color:'#3a6ea5',bootVendor:'YFGeek',bootProduct:'2000',bootBadge:'Professional',bootTagline:'Built on NT Technology'},
  winxp:{version:'XP',edition:'Professional',name:'YFGeek XP',tagline:'YFGeek Desktop',color:'#245edb',bootVendor:'yfgeek.com',bootProduct:'YFGeek',bootBadge:'xp',bootTagline:'Professional'}
};
let pendingTheme='winxp';
function setShellText(selector,value){const element=$(selector);if(element)element.textContent=value}
function applyShellTheme(name,save=false){
  if(!shellThemes.includes(name))return;
  activeShellTheme=name;
  document.documentElement.dataset.bootTheme=name;
  document.body.classList.remove('win2000',...shellThemes.map(theme=>`theme-${theme}`));
  document.body.classList.add(`theme-${name}`);
  if(name==='win2000')document.body.classList.add('win2000');
  const details=shellThemeDetails[name];
  setShellText('#shellVersion',details.version);
  setShellText('#shellEdition',details.edition);
  setShellText('#bootVendor',details.bootVendor);
  setShellText('#bootProductName',details.bootProduct);
  setShellText('#bootEdition',details.bootBadge);
  setShellText('#bootTagline',details.bootTagline);
  setShellText('#aboutVersionMark',details.version);
  setShellText('#aboutSystemName',`YFGeek ${details.version}`);
  setShellText('#aboutThemeDescription',`${details.name} 风格个人简历`);
  $('#desktop').setAttribute('aria-label',`极客凡的 ${details.name} 桌面`);
  $('meta[name="theme-color"]').content=details.color;
  $('#themePreview').dataset.themePreview=name;
  $('#shellThemeSelect').value=name;
  if(save)try{localStorage.setItem('yf-shell-theme-v2',name)}catch{}
  applySystemIcons();
  updateTasks();
}
function applyWallpaper(name,save=false){if(!wallpaperNames.includes(name))return;wallpaperNames.forEach(x=>$('#desktop').classList.remove(`wallpaper-${x}`));$('#desktop').classList.add(`wallpaper-${name}`);if(save)try{localStorage.setItem('yf-wallpaper-v2',name)}catch{} }
try{const saved=localStorage.getItem('yf-wallpaper-v2');if(saved){pendingWallpaper=saved;applyWallpaper(saved)}}catch{}
try{const saved=localStorage.getItem('yf-shell-theme-v2');if(shellThemes.includes(saved))pendingTheme=saved}catch{}
applyShellTheme(pendingTheme);
function bindTouchControl(element,action){let touchAt=0;element.addEventListener('pointerup',event=>{if(event.pointerType!=='touch')return;event.preventDefault();touchAt=Date.now();action(event)});element.addEventListener('click',event=>{if(Date.now()-touchAt<450){event.preventDefault();return}action(event)})}
function selectWallpaper(button){pendingWallpaper=button.dataset.wallpaper;$$('[data-wallpaper]').forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-selected',String(selected))});const preview=$('#wallpaperPreview'),style=wallpaperPreviews[pendingWallpaper];preview.style.backgroundImage=style.image;preview.style.backgroundColor=style.color}
function activateDisplayTab(tab,{focus=false}={}){$$('[data-display-tab]').forEach(button=>{const active=button===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});$$('[data-display-panel]').forEach(panel=>{const active=panel.dataset.displayPanel===tab.dataset.displayTab;panel.classList.toggle('active',active);panel.hidden=!active});if(focus)tab.focus()}
$$('[data-wallpaper]').forEach(button=>bindTouchControl(button,()=>selectWallpaper(button)));
const displayTabs=$$('[data-display-tab]');
displayTabs.forEach((tab,index)=>{bindTouchControl(tab,()=>activateDisplayTab(tab));tab.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?displayTabs.length-1:(index+(event.key==='ArrowRight'?1:-1)+displayTabs.length)%displayTabs.length;activateDisplayTab(displayTabs[next],{focus:true})})});
function selectShellThemeChoice(name){if(!shellThemes.includes(name))return;pendingTheme=name;$('#shellThemeSelect').value=name;$('#themePreview').dataset.themePreview=name;$$('[data-theme-choice]').forEach(button=>button.classList.toggle('selected',button.dataset.themeChoice===name))}
$('#shellThemeSelect').addEventListener('change',event=>selectShellThemeChoice(event.target.value));
$('#shellThemeSelect').addEventListener('input',event=>selectShellThemeChoice(event.target.value));
$$('[data-theme-choice]').forEach(button=>bindTouchControl(button,()=>selectShellThemeChoice(button.dataset.themeChoice)));
const displayResolutions=[{label:'640 × 480',width:640,height:480},{label:'800 × 600',width:800,height:600},{label:'1024 × 768',width:1024,height:768},{label:'1280 × 1024',width:1280,height:1024},{label:'最佳适配',fit:true}];
const resolutionRange=$('#resolutionRange'),resolutionOutput=$('#resolutionOutput'),resolutionPreviewValue=$('#resolutionPreviewValue'),touchScaleEnabled=$('#touchScaleEnabled');
let pendingResolution=displayResolutions.length-1,pendingTouchScale=true,appliedResolution=displayResolutions.length-1,appliedTouchScale=true;
try{const storedResolution=localStorage.getItem('yf-display-resolution-v2'),saved=Number(storedResolution);if(storedResolution!==null&&Number.isInteger(saved)&&saved>=0&&saved<displayResolutions.length)pendingResolution=appliedResolution=saved;pendingTouchScale=appliedTouchScale=localStorage.getItem('yf-touch-scale-v1')!=='off'}catch{}
function viewportResolution(){return{label:`最佳适配（${innerWidth} × ${innerHeight}）`,width:innerWidth,height:innerHeight,fit:true}}
function selectedDisplayResolution(index=pendingResolution){const resolution=displayResolutions[index];return resolution?.fit?viewportResolution():resolution}
function updateDisplaySettingsPreview(){const resolution=selectedDisplayResolution();resolutionRange.value=String(pendingResolution);resolutionOutput.textContent=resolution.label;resolutionPreviewValue.textContent=resolution.label;touchScaleEnabled.checked=pendingTouchScale;$('.resolution-preview').style.setProperty('--preview-ratio',`${resolution.width}/${resolution.height}`)}
function updateVirtualResolutionLayout(){if(typeof appliedResolution==='undefined')return;const resolution=selectedDisplayResolution(appliedResolution),root=document.documentElement.style;if(resolution.fit||isMobileOrTablet()){document.body.classList.remove('virtual-resolution-active');root.removeProperty('--virtual-width');root.removeProperty('--virtual-desktop-height');root.removeProperty('--resolution-scale');root.removeProperty('--resolution-offset-x');root.removeProperty('--resolution-offset-y');root.removeProperty('--resolution-taskbar-top');if(pendingResolution===appliedResolution&&resolution.fit)updateDisplaySettingsPreview();return}const task=Math.max(24,parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--task'))||30),scale=Math.min(innerWidth/resolution.width,innerHeight/resolution.height),offsetX=Math.max(0,(innerWidth-resolution.width*scale)/2),offsetY=Math.max(0,(innerHeight-resolution.height*scale)/2);root.setProperty('--virtual-width',`${resolution.width}px`);root.setProperty('--virtual-desktop-height',`${resolution.height-task}px`);root.setProperty('--resolution-scale',String(scale));root.setProperty('--resolution-offset-x',`${offsetX}px`);root.setProperty('--resolution-offset-y',`${offsetY}px`);root.setProperty('--resolution-taskbar-top',`${offsetY+(resolution.height-task)*scale}px`);document.body.classList.add('virtual-resolution-active')}
function applyDisplaySettings(save=false){appliedResolution=pendingResolution;appliedTouchScale=pendingTouchScale;document.body.dataset.resolution=String(appliedResolution);document.body.classList.toggle('touch-controls-compact',!appliedTouchScale);updateVirtualResolutionLayout();if(save)try{localStorage.setItem('yf-display-resolution-v2',String(appliedResolution));localStorage.removeItem('yf-display-resolution-v1');localStorage.setItem('yf-touch-scale-v1',appliedTouchScale?'on':'off')}catch{}requestAnimationFrame(()=>{arrangeDesktop();$$('.remote-game-window:not(.hidden)').forEach(fitRemoteGame);fitDosWindow($('#window-dos:not(.hidden)'))})}
function setPendingResolution(value){pendingResolution=Math.max(0,Math.min(displayResolutions.length-1,Number(value)||0));updateDisplaySettingsPreview()}
resolutionRange.addEventListener('input',event=>setPendingResolution(event.target.value));
resolutionRange.addEventListener('change',event=>setPendingResolution(event.target.value));
let touchCheckboxAt=0;
touchScaleEnabled.closest('label').addEventListener('pointerup',event=>{if(event.pointerType!=='touch')return;event.preventDefault();event.stopPropagation();touchCheckboxAt=Date.now();touchScaleEnabled.checked=!touchScaleEnabled.checked;touchScaleEnabled.dispatchEvent(new Event('change',{bubbles:true}))});
touchScaleEnabled.closest('label').addEventListener('click',event=>{if(Date.now()-touchCheckboxAt<500){event.preventDefault();event.stopPropagation()}});
touchScaleEnabled.addEventListener('change',()=>{pendingTouchScale=touchScaleEnabled.checked;updateDisplaySettingsPreview()});
updateDisplaySettingsPreview();applyDisplaySettings();
$('#screensaverSelect').addEventListener('change',event=>{const preview=$('.screensaver-preview'),none=event.target.value==='无';preview.classList.toggle('disabled',none);preview.querySelector('span').textContent=event.target.value==='星空'?'✦ YFG ✦':'YFG'});
$('[data-apply-wallpaper]').addEventListener('click',()=>{applyWallpaper(pendingWallpaper,true);applyShellTheme(pendingTheme,true);applyDisplaySettings(true)});
$('[data-save-wallpaper]').addEventListener('click',()=>{applyWallpaper(pendingWallpaper,true);applyShellTheme(pendingTheme,true);applyDisplaySettings(true);closeWindow($('#window-display'))});
$('[data-cancel-display]').addEventListener('click',()=>{pendingResolution=appliedResolution;pendingTouchScale=appliedTouchScale;updateDisplaySettingsPreview();closeWindow($('#window-display'))});

// Photo folders can use bundled gallery assets or a visitor-selected local directory.
const galleryObjectUrls={travel:[],food:[]};
function galleryConfig(kind){return{stage:$(`#${kind}Gallery`),path:$(`#${kind}GalleryPath`),count:$(`#${kind}GalleryCount`)}}
function clearGalleryUrls(kind){galleryObjectUrls[kind].forEach(URL.revokeObjectURL);galleryObjectUrls[kind]=[]}
function showGalleryPreview(item){const win=item.closest('.gallery-window'),overlay=document.createElement('div');overlay.className='gallery-lightbox';const close=document.createElement('button');close.type='button';close.setAttribute('aria-label','关闭预览');close.textContent='×';const image=document.createElement('img');image.src=item.dataset.gallerySrc;image.alt=item.querySelector('span')?.textContent||'照片预览';overlay.append(close,image);close.addEventListener('click',()=>overlay.remove());overlay.addEventListener('click',event=>{if(event.target===overlay)overlay.remove()});win.append(overlay);playSystemSound('open')}
function bindGalleryItem(item){if(item.dataset.galleryBound)return;item.dataset.galleryBound='true';item.addEventListener('click',()=>{item.parentElement.querySelectorAll('.gallery-item').forEach(x=>x.classList.remove('file-selected'));item.classList.add('file-selected');if(isMobileOrTablet())showGalleryPreview(item)});item.addEventListener('dblclick',()=>{if(!isMobileOrTablet())showGalleryPreview(item)});item.addEventListener('keydown',event=>{if(event.key==='Enter')showGalleryPreview(item)})}
function renderGallery(kind,items,pathLabel){const {stage,path,count}=galleryConfig(kind);clearGalleryUrls(kind);stage.innerHTML='';items.forEach(entry=>{const button=document.createElement('button');button.className='gallery-item';button.dataset.gallerySrc=entry.url;const image=document.createElement('img'),label=document.createElement('span');image.src=entry.url;image.alt='';label.textContent=entry.name;button.append(image,label);stage.append(button);bindGalleryItem(button);if(entry.objectUrl)galleryObjectUrls[kind].push(entry.url)});if(!items.length){const empty=document.createElement('div');empty.className='gallery-empty';empty.innerHTML='<img src="assets/icons/Camera_32x32_4.png" alt=""><span>此文件夹中没有图像。</span>';stage.append(empty)}path.textContent=pathLabel;count.textContent=`${items.length} 个图像`}
async function collectGalleryFiles(handle,prefix=''){const files=[];for await(const entry of handle.values()){if(entry.kind==='directory')files.push(...await collectGalleryFiles(entry,`${prefix}${entry.name}\\`));else if(/\.(?:avif|bmp|gif|jpe?g|png|webp)$/i.test(entry.name))files.push({file:await entry.getFile(),name:`${prefix}${entry.name}`})}return files.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))}
function openGalleryDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('yfgeek98-galleries',1);request.onupgradeneeded=()=>request.result.createObjectStore('handles');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function saveGalleryHandle(kind,handle){try{const db=await openGalleryDatabase(),transaction=db.transaction('handles','readwrite');transaction.objectStore('handles').put(handle,kind);await new Promise((resolve,reject)=>{transaction.oncomplete=resolve;transaction.onerror=()=>reject(transaction.error)});db.close()}catch{}}
async function readGalleryHandle(kind){try{const db=await openGalleryDatabase(),transaction=db.transaction('handles'),request=transaction.objectStore('handles').get(kind),handle=await new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});db.close();return handle}catch{return null}}
async function loadGalleryHandle(kind,handle){const files=await collectGalleryFiles(handle),items=files.map(entry=>{const url=URL.createObjectURL(entry.file);return{name:entry.name,url,objectUrl:true}});renderGallery(kind,items,`C:\\${handle.name}`)}
function pickGalleryFallback(kind){const input=document.createElement('input');input.type='file';input.accept='image/*';input.multiple=true;input.webkitdirectory=true;input.addEventListener('change',()=>{const files=[...input.files].filter(file=>file.type.startsWith('image/')).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN')),folder=files[0]?.webkitRelativePath.split('/')[0]||'照片目录',items=files.map(file=>({name:file.webkitRelativePath||file.name,url:URL.createObjectURL(file),objectUrl:true}));renderGallery(kind,items,`C:\\${folder}`)});input.click()}
async function pickGalleryDirectory(kind){if(!window.showDirectoryPicker){pickGalleryFallback(kind);return}try{const handle=await window.showDirectoryPicker({id:`yfgeek98-${kind}`,mode:'read'});await saveGalleryHandle(kind,handle);await loadGalleryHandle(kind,handle)}catch(error){if(error.name!=='AbortError')showSystemDialog({title:'照片目录',message:'无法读取所选目录，请检查访问权限后重试。',type:'error'})}}
async function loadBundledGalleries(){try{const manifest=await fetch('assets/galleries/manifest.json').then(response=>response.ok?response.json():Promise.reject());for(const kind of ['travel','food'])if(manifest[kind]?.length)renderGallery(kind,manifest[kind].map(path=>({name:path.split('/').at(-1),url:`assets/galleries/${kind}/${path}`})),`C:\\YFGeek\\Photos\\${kind==='travel'?'Travel':'Food'}`)}catch{}}
async function restoreGalleryHandles(){for(const kind of ['travel','food']){const handle=await readGalleryHandle(kind);if(!handle)continue;try{if(await handle.queryPermission({mode:'read'})==='granted')await loadGalleryHandle(kind,handle)}catch{}}}
$$('[data-gallery-pick]').forEach(button=>button.addEventListener('click',()=>pickGalleryDirectory(button.dataset.galleryPick)));
$$('.gallery-item').forEach(bindGalleryItem);
loadBundledGalleries().finally(restoreGalleryHandles);

// A visitor-selected My Documents folder remains outside the site bundle and is edited through explicit file permissions.
const editorFileState={word:null,notepad:null,excel:null,powerpoint:null};
const editorDefaults={word:'极客凡_个人简历.doc',notepad:'文本文档.txt',excel:'工作簿.csv',powerpoint:'演示文稿.ppt'};
function currentDocumentsHandle(){return documentsDirectoryStack.at(-1)?.handle||null}
function localExtension(name){const dot=String(name||'').lastIndexOf('.');return dot>=0?name.slice(dot).toLowerCase():''}
function localFileType(name){const ext=localExtension(name);if(['.doc','.docx','.rtf','.html','.htm'].includes(ext))return['word','YFGeek Word 文档'];if(['.csv','.tsv','.xls','.xlsx'].includes(ext))return['excel','YFGeek Excel 工作表'];if(['.ppt','.pps','.pptx'].includes(ext))return['powerpoint','YFGeek PowerPoint 演示文稿'];if(['.txt','.md','.log','.json','.js','.css','.xml'].includes(ext))return['notepad','文本文档'];return['file','文件']}
function appendLocalFileIcon(button,type){if(['word','excel','powerpoint'].includes(type)){const icon=document.createElement('span');icon.className=`office-doc-icon ${type==='word'?'word-color':type==='excel'?'excel-color':'ppt-color'}`;icon.textContent=type==='word'?'W':type==='excel'?'X':'P';button.append(icon);return}const image=document.createElement('img');image.className='folder-item-icon';image.src=`assets/icons/${type==='notepad'?'Notepad':'FileText'}_32x32_4.png`;image.alt='';button.append(image)}
function createLocalDocumentItem(handle,parent){const button=document.createElement('button'),name=document.createElement('b'),detail=document.createElement('small');name.textContent=handle.name;if(handle.kind==='directory'){const image=setSystemImage(document.createElement('img'),'folder');image.className='folder-item-icon';image.alt='';button.append(image);detail.textContent='文件夹'}else{const [type,label]=localFileType(handle.name);appendLocalFileIcon(button,type);detail.textContent=label}button.append(name,detail);if(handle.readOnly||!parent?.removeEntry)button.dataset.protected='true';localEntryHandles.set(button,handle);if(parent)localEntryParents.set(button,parent);bindShellItem(button);return button}
function updateDocumentsChrome(label,count,status='可直接打开和保存'){const path=$('#documentsAddress'),access=$('#documentsAccess');path.textContent=label;access.textContent=documentsRootHandle?'本地目录 · 可读写':'只读目录';$('#documentsCount').textContent=`${count} 个对象`;$('#documentsStatus').textContent=status;$('#documentsRefresh').disabled=false}
async function renderDocumentsDirectory(handle){if(!handle)return;const body=$('#documentsBody');try{const entries=[];for await(const entry of handle.values())entries.push(entry);entries.sort((a,b)=>a.kind===b.kind?a.name.localeCompare(b.name,'zh-CN'):a.kind==='directory'?-1:1);body.innerHTML='';body.classList.toggle('documents-empty',entries.length===0);entries.forEach(entry=>body.append(createLocalDocumentItem(entry,handle)));if(!entries.length){const empty=document.createElement('div'),image=setSystemImage(document.createElement('img'),'folder');empty.className='documents-empty-message';image.alt='';empty.append(image,Object.assign(document.createElement('span'),{textContent:'此文件夹为空。'}));body.append(empty)}const path=['C:',...documentsDirectoryStack.map(entry=>entry.name)].join('\\');updateDocumentsChrome(path,entries.length);refreshExplorerCommands($('#window-documents'))}catch{$('#documentsStatus').textContent='需要重新授权目录';$('#documentsAccess').textContent='等待授权'}}
async function requestDocumentsPermission(handle=documentsRootHandle){if(!handle?.queryPermission)return true;let permission=await handle.queryPermission({mode:'readwrite'});if(permission!=='granted'&&handle.requestPermission)permission=await handle.requestPermission({mode:'readwrite'});return permission==='granted'}
async function setDocumentsRoot(handle){documentsRootHandle=handle;documentsDirectoryStack=[{name:handle.name,handle}];await saveGalleryHandle('documents',handle);await renderDocumentsDirectory(handle)}
function pickDocumentsFallback(){const input=document.createElement('input');input.type='file';input.multiple=true;input.webkitdirectory=true;input.addEventListener('change',()=>{const files=[...input.files],folder=files[0]?.webkitRelativePath.split('/')[0]||'My Documents',handles=files.map(file=>({kind:'file',name:file.webkitRelativePath||file.name,readOnly:true,getFile:async()=>file})),body=$('#documentsBody');documentsRootHandle=null;documentsDirectoryStack=[];body.innerHTML='';handles.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN')).forEach(handle=>body.append(createLocalDocumentItem(handle,null)));updateDocumentsChrome(`C:\\${folder}`,handles.length,'只读预览；保存时请选择文件位置')});input.click()}
async function pickDocumentsDirectory(){if(!window.showDirectoryPicker){pickDocumentsFallback();return}try{const handle=await window.showDirectoryPicker({id:'yfgeek98-documents',mode:'readwrite'});if(!await requestDocumentsPermission(handle))return;await setDocumentsRoot(handle);playSystemSound('open')}catch(error){if(error.name!=='AbortError')showSystemDialog({title:'我的文档',message:'无法打开所选目录，请检查读写权限。',type:'error'})}}
async function refreshDocumentsDirectory(){if(!documentsRootHandle){pickDocumentsDirectory();return}try{if(!await requestDocumentsPermission())return;await renderDocumentsDirectory(currentDocumentsHandle())}catch{showSystemDialog({title:'我的文档',message:'无法刷新目录，请重新选择。',type:'error'})}}
async function restoreDocumentsDirectory(){const handle=await readGalleryHandle('documents');if(!handle)return;documentsRootHandle=handle;documentsDirectoryStack=[{name:handle.name,handle}];try{if(await handle.queryPermission({mode:'readwrite'})==='granted')await renderDocumentsDirectory(handle);else{$('#documentsAccess').textContent='点击刷新以授权';$('#documentsRefresh').disabled=false}}catch{}}
async function goUpDocumentsDirectory(){if(documentsDirectoryStack.length<=1)return;documentsDirectoryStack.pop();await renderDocumentsDirectory(currentDocumentsHandle())}
async function openLocalEntry(item){const handle=localEntryHandles.get(item),parent=localEntryParents.get(item);if(!handle)return;if(handle.kind==='directory'){documentsDirectoryStack.push({name:handle.name,handle});await renderDocumentsDirectory(handle);return}await openLocalFile(handle,parent)}
restoreDocumentsDirectory();

function decodeRtf(text){return text.replace(/\\u(-?\d+)\??/g,(_,n)=>String.fromCharCode(Number(n)<0?Number(n)+65536:Number(n))).replace(/\\par[d]?\b/g,'\n').replace(/\\'[0-9a-f]{2}/gi,'').replace(/\\[a-z]+-?\d* ?/gi,'').replace(/[{}]/g,'').trim()}
function textToWordHtml(text){return text.split(/\r?\n/).map(line=>`<p>${escapeHtml(line)||'<br>'}</p>`).join('')}
function parseDelimited(text,delimiter){const rows=[],row=[];let field='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(quoted){if(char==='"'&&text[i+1]==='"'){field+='"';i++}else if(char==='"')quoted=false;else field+=char}else if(char==='"')quoted=true;else if(char===delimiter){row.push(field);field=''}else if(char==='\n'){row.push(field.replace(/\r$/,''));rows.push(row.splice(0));field=''}else field+=char}row.push(field.replace(/\r$/,''));if(row.some(value=>value!==''))rows.push(row);return rows}
function buildExcelSheet(rows){const table=$('#excelSheet'),width=Math.max(1,Math.min(26,rows.length?Math.max(...rows.map(row=>row.length)):5)),thead=document.createElement('thead'),head=document.createElement('tr'),tbody=document.createElement('tbody');head.appendChild(document.createElement('th'));for(let i=0;i<width;i++){const th=document.createElement('th');th.textContent=String.fromCharCode(65+i);head.append(th)}thead.append(head);rows.forEach((row,index)=>{const tr=document.createElement('tr'),th=document.createElement('th');th.textContent=index+1;tr.append(th);for(let i=0;i<width;i++){const td=document.createElement('td');td.contentEditable='true';td.textContent=row[i]||'';tr.append(td)}tbody.append(tr)});table.replaceChildren(thead,tbody)}
function excelRows(){return [...$('#excelSheet tbody').rows].map(row=>[...row.cells].slice(1).map(cell=>cell.innerText))}
function serializeDelimited(rows,delimiter){return rows.map(row=>row.map(value=>{const text=String(value??'');return /["\r\n,\t]/.test(text)?`"${text.replace(/"/g,'""')}"`:text}).join(delimiter)).join('\r\n')}
function editorTitle(app,name){if(app==='word')$('#wordTitle').textContent=`${name} - YFGeek Word`;if(app==='notepad')$('#notepadTitle').textContent=`${name} - 记事本`;if(app==='excel')$('#excelTitle').textContent=`${name} - YFGeek Excel`;if(app==='powerpoint')$('#powerpointTitle').textContent=`${name} - YFGeek PowerPoint`}
function editorStatus(app,text){const win=getWindow(app),status=app==='word'?$('#wordStatus'):app==='notepad'?$('#noteStatus'):win?.querySelector('.statusbar span:last-child');if(status)status.textContent=text}
async function loadFileIntoEditor(app,handle,parent=null){const file=await handle.getFile();if(file.size>15*1024*1024){showSystemDialog({title:'打开文件',message:'文件超过 15 MB，网页版编辑器暂不打开。',type:'error'});return}const text=(await file.text()).replace(/^\uFEFF/,''),ext=localExtension(file.name);if(/\.(?:docx|xlsx|pptx)$/.test(ext)||text.includes('\0')){showSystemDialog({title:'YFGeek Office XP',message:'这是现代或二进制 Office 文件，网页端不会直接改写，以免损坏原文件。请在桌面 Office 中编辑，或另存为 DOC/CSV/PPT 兼容格式。',type:'info'});return}if(app==='word'){let html;if(/^\s*{\\rtf/i.test(text))html=textToWordHtml(decodeRtf(text));else if(/<\/?(?:html|body|p|div|section|h[1-6]|table)\b/i.test(text)){const parsed=new DOMParser().parseFromString(text,'text/html');html=parsed.body.innerHTML}else html=textToWordHtml(text);wordDoc.innerHTML=safeWordHtml(html);wordDirty=false;updateWordCount()}else if(app==='notepad'){note.value=text;updateNotePosition()}else if(app==='excel'){if(/<table\b/i.test(text)){const parsed=new DOMParser().parseFromString(text,'text/html'),rows=[...parsed.querySelectorAll('table tr')].map(row=>[...row.cells].map(cell=>cell.textContent));buildExcelSheet(rows)}else buildExcelSheet(parseDelimited(text,ext==='.tsv'?'\t':','))}else if(app==='powerpoint'){const parsed=new DOMParser().parseFromString(text,'text/html'),slide=parsed.querySelector('.ppt-slide');$('.ppt-slide').innerHTML=safeWordHtml(slide?slide.innerHTML:textToWordHtml(text))}const rtfReadOnly=app==='word'&&ext==='.rtf';editorFileState[app]={handle:rtfReadOnly?null:handle,parent:rtfReadOnly?null:parent,name:rtfReadOnly?file.name.replace(/\.rtf$/i,'.doc'):file.name};editorTitle(app,file.name);editorStatus(app,rtfReadOnly?'RTF 已打开；请另存为 DOC':'已打开本地文件');openApp(app)}
async function openLocalFile(handle,parent=null){const ext=localExtension(handle.name),[type]=localFileType(handle.name);if(['.docx','.xlsx','.pptx'].includes(ext)){showSystemDialog({title:'打开文件',message:'DOCX、XLSX、PPTX 是压缩的现代 Office 格式。网页版不会直接改写，请使用桌面 Office，或保存为 DOC、CSV、PPT 兼容格式。',type:'info'});return}if(type==='file'){try{const file=await handle.getFile();if(!file.type.startsWith('text/'))throw new Error();await loadFileIntoEditor('notepad',handle,parent)}catch{showSystemDialog({title:'打开文件',message:'没有可用于打开此文件的网页程序。',type:'error'})}return}await loadFileIntoEditor(type,handle,parent)}
function editorPickerTypes(app){return{word:[{description:'Word 兼容文档',accept:{'application/msword':['.doc'],'text/html':['.html','.htm'],'application/rtf':['.rtf']}}],notepad:[{description:'文本文件',accept:{'text/plain':['.txt','.md','.log','.json']}}],excel:[{description:'Excel 兼容文件',accept:{'text/csv':['.csv'],'text/tab-separated-values':['.tsv'],'application/vnd.ms-excel':['.xls']}}],powerpoint:[{description:'PowerPoint 兼容文件',accept:{'application/vnd.ms-powerpoint':['.ppt','.pps'],'text/html':['.html']}}]}[app]}
async function openEditorFile(app){if(!window.showOpenFilePicker){const input=document.createElement('input');input.type='file';input.accept=editorPickerTypes(app)[0].accept?Object.values(editorPickerTypes(app)[0].accept).flat().join(','):'';input.addEventListener('change',()=>{const file=input.files[0];if(file)loadFileIntoEditor(app,{kind:'file',name:file.name,readOnly:true,getFile:async()=>file})});input.click();return}try{const [handle]=await window.showOpenFilePicker({id:`yfgeek98-open-${app}`,multiple:false,types:editorPickerTypes(app)});if(handle)await loadFileIntoEditor(app,handle)}catch(error){if(error.name!=='AbortError')showSystemDialog({title:'打开文件',message:'无法读取所选文件。',type:'error'})}}
function editorPayload(app,name){if(app==='word')return `<!doctype html><html><head><meta charset="UTF-8"><meta name="ProgId" content="Word.Document"></head><body>${safeWordHtml(wordDoc.innerHTML)}</body></html>`;if(app==='notepad')return note.value;if(app==='excel'){const rows=excelRows(),ext=localExtension(name);return ext==='.xls'?`<!doctype html><html><head><meta charset="UTF-8"></head><body>${$('#excelSheet').outerHTML}</body></html>`:serializeDelimited(rows,ext==='.tsv'?'\t':',')}return `<!doctype html><html><head><meta charset="UTF-8"><meta name="ProgId" content="PowerPoint.Show"></head><body>${$('.ppt-slide').outerHTML}</body></html>`}
async function uniqueLocalName(directory,name){const names=new Set();for await(const entry of directory.values())names.add(entry.name);if(!names.has(name))return name;const dot=name.lastIndexOf('.'),stem=dot>0?name.slice(0,dot):name,ext=dot>0?name.slice(dot):'';let index=2,candidate=`${stem} - 副本${ext}`;while(names.has(candidate))candidate=`${stem} - 副本 (${index++})${ext}`;return candidate}
async function writeEditorFile(app,handle,name){const writable=await handle.createWritable();await writable.write(editorPayload(app,name));await writable.close();editorFileState[app]={...(editorFileState[app]||{}),handle,name};editorTitle(app,name);editorStatus(app,'已保存到本地文件');if(app==='word')wordDirty=false;if(documentsRootHandle)await renderDocumentsDirectory(currentDocumentsHandle())}
function downloadEditorFile(app,name){const mime={word:'application/msword',notepad:'text/plain;charset=utf-8',excel:localExtension(name)==='.csv'?'text/csv;charset=utf-8':'application/vnd.ms-excel',powerpoint:'application/vnd.ms-powerpoint'}[app],url=URL.createObjectURL(new Blob(['\uFEFF',editorPayload(app,name)],{type:mime})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);editorStatus(app,'文件已生成并下载')}
async function saveEditor(app,{saveAs=false}={}){try{let state=editorFileState[app],handle=saveAs?null:state?.handle,name=state?.name||editorDefaults[app];if(saveAs&&window.showSaveFilePicker){handle=await window.showSaveFilePicker({id:`yfgeek98-save-${app}`,suggestedName:name,types:editorPickerTypes(app)});name=handle.name}else if(!handle&&documentsRootHandle&&await requestDocumentsPermission()){const directory=currentDocumentsHandle();name=await uniqueLocalName(directory,name);handle=await directory.getFileHandle(name,{create:true});state={parent:directory}}if(handle?.createWritable){editorFileState[app]={handle,parent:state?.parent||null,name};await writeEditorFile(app,handle,name);return}if(saveAs){downloadEditorFile(app,name);return}if(app==='word'){localStorage.setItem('yf-word97-resume',safeWordHtml(wordDoc.innerHTML));wordDirty=false}else if(app==='notepad')localStorage.setItem('yf-notepad',note.value);editorStatus(app,'已保存到浏览器；“另存为”可生成文件')}catch(error){if(error.name!=='AbortError')showSystemDialog({title:'保存文件',message:'保存失败，请检查文件或目录写入权限。',type:'error'})}}
async function copyLocalHandle(source,target,name){if(source.kind==='file'){const file=await source.getFile(),targetFile=await target.getFileHandle(name,{create:true}),writable=await targetFile.createWritable();await writable.write(file);await writable.close();return}const directory=await target.getDirectoryHandle(name,{create:true});for await(const entry of source.values())await copyLocalHandle(entry,directory,entry.name)}
async function isSameLocalEntry(a,b){try{return a===b||Boolean(a?.isSameEntry&&await a.isSameEntry(b))}catch{return a===b}}
async function pasteLocalShellItems(){const target=currentDocumentsHandle(),entries=shellClipboard?.entries||[];if(!target||!entries.length)return;if(entries.some(entry=>!entry.localHandle)){showSystemDialog({title:'粘贴',message:'绑定目录只能粘贴真实文件或文件夹。',type:'info'});return}try{if(!await requestDocumentsPermission())return;for(const entry of entries){if(shellClipboard.mode==='cut'&&await isSameLocalEntry(entry.localParent,target))continue;if(entry.localHandle.kind==='directory'){let insideSource=false;for(const directory of documentsDirectoryStack)if(await isSameLocalEntry(entry.localHandle,directory.handle)){insideSource=true;break}if(insideSource){showSystemDialog({title:'粘贴',message:'不能把文件夹复制到它自身内部。',type:'error'});return}}const name=await uniqueLocalName(target,entry.localHandle.name);await copyLocalHandle(entry.localHandle,target,name);if(shellClipboard.mode==='cut'&&entry.localParent?.removeEntry)await entry.localParent.removeEntry(entry.localHandle.name,{recursive:true})}if(shellClipboard.mode==='cut')shellClipboard=null;await renderDocumentsDirectory(target);playSystemSound('open')}catch{showSystemDialog({title:'粘贴',message:'无法写入目标目录，请检查目录权限。',type:'error'})}}

// Notepad
const note=$('#notepadEditor');
try{const savedNote=localStorage.getItem('yf-notepad');if(savedNote)note.value=savedNote}catch{}
function noteNew(){editorFileState.notepad=null;note.value='';note.focus();$('#notepadTitle').textContent='无标题 - 记事本';$('#noteStatus').textContent='新文档';updateNotePosition()}
function noteSave(){saveEditor('notepad')}
function updateNotePosition(){const before=note.value.slice(0,note.selectionStart),lines=before.split('\n');$('#notePosition').textContent=`第 ${lines.length} 行，第 ${lines.at(-1).length+1} 列`}
note.addEventListener('input',()=>{$('#noteStatus').textContent='已修改';$('#notepadTitle').textContent=`*${editorFileState.notepad?.name||'无标题'} - 记事本`;updateNotePosition()});
['click','keyup','select'].forEach(type=>note.addEventListener(type,updateNotePosition));
note.addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();note.setRangeText('\t',note.selectionStart,note.selectionEnd,'end');updateNotePosition()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();noteSave()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();noteNew()}});updateNotePosition();

// Office XP editors
const wordDoc=$('#wordDocument');let wordDirty=false;
const wordWorkspace=$('.word-workspace'),wordScrollBar=$('#wordScrollBar'),wordScrollTrack=wordScrollBar.querySelector('.office-scroll-track'),wordScrollThumb=wordScrollTrack.querySelector('i');
let wordScrollDrag=null;
function syncWordScrollbar(){const max=Math.max(0,wordWorkspace.scrollHeight-wordWorkspace.clientHeight),trackHeight=wordScrollTrack.clientHeight,thumbHeight=Math.max(24,Math.round(trackHeight*wordWorkspace.clientHeight/Math.max(wordWorkspace.scrollHeight,1))),travel=Math.max(0,trackHeight-thumbHeight),value=max?wordWorkspace.scrollTop/max:0;wordScrollThumb.style.height=`${Math.min(trackHeight,thumbHeight)}px`;wordScrollThumb.style.top=`${Math.round(travel*value)}px`;wordScrollThumb.setAttribute('aria-valuenow',String(Math.round(value*100)));wordScrollBar.classList.toggle('scroll-disabled',max===0)}
function scrollWordFromThumb(top){const travel=Math.max(1,wordScrollTrack.clientHeight-wordScrollThumb.offsetHeight),max=Math.max(0,wordWorkspace.scrollHeight-wordWorkspace.clientHeight);wordWorkspace.scrollTop=Math.max(0,Math.min(travel,top))/travel*max}
wordWorkspace.addEventListener('scroll',syncWordScrollbar,{passive:true});
wordScrollBar.querySelectorAll('[data-scroll-step]').forEach(button=>button.addEventListener('click',()=>wordWorkspace.scrollBy({top:Number(button.dataset.scrollStep)*56,behavior:'auto'})));
wordScrollTrack.addEventListener('pointerdown',event=>{if(event.target===wordScrollThumb)return;const rect=wordScrollTrack.getBoundingClientRect();scrollWordFromThumb(event.clientY-rect.top-wordScrollThumb.offsetHeight/2)});
wordScrollThumb.addEventListener('pointerdown',event=>{event.preventDefault();wordScrollDrag={pointerId:event.pointerId,startY:event.clientY,startTop:wordScrollThumb.offsetTop};wordScrollThumb.setPointerCapture(event.pointerId)});
wordScrollThumb.addEventListener('pointermove',event=>{if(!wordScrollDrag||event.pointerId!==wordScrollDrag.pointerId)return;scrollWordFromThumb(wordScrollDrag.startTop+event.clientY-wordScrollDrag.startY)});
wordScrollThumb.addEventListener('pointerup',event=>{if(wordScrollDrag?.pointerId===event.pointerId)wordScrollDrag=null});
wordScrollThumb.addEventListener('pointercancel',()=>wordScrollDrag=null);
wordScrollThumb.addEventListener('keydown',event=>{if(event.key==='ArrowUp'||event.key==='ArrowDown'){event.preventDefault();wordWorkspace.scrollBy({top:event.key==='ArrowUp'?-56:56})}if(event.key==='Home'||event.key==='End'){event.preventDefault();wordWorkspace.scrollTop=event.key==='Home'?0:wordWorkspace.scrollHeight}});
if(typeof ResizeObserver==='function'){const wordScrollObserver=new ResizeObserver(syncWordScrollbar);wordScrollObserver.observe(wordWorkspace);wordScrollObserver.observe(wordDoc)}
requestAnimationFrame(syncWordScrollbar);
function safeWordHtml(html){const t=document.createElement('template');t.innerHTML=html;t.content.querySelectorAll('script,iframe,object,embed').forEach(x=>x.remove());t.content.querySelectorAll('*').forEach(x=>[...x.attributes].forEach(a=>{if(a.name.startsWith('on')||/javascript:/i.test(a.value))x.removeAttribute(a.name)}));return t.innerHTML}
function anonymizeLegacyResume(value){const template=document.createElement('template');template.innerHTML=String(value).replaceAll('\u5434\u4e00\u51e1','极客凡').replaceAll('\u4e00\u51e1','极客凡').replace(new RegExp(['YI','FAN'].join(''),'gi'),'YFGEEK').replaceAll(['W','Y','F'].join(''),'YFG').replaceAll(['开发组','组长'].join(''),'技术负责人').replaceAll(['开发','组长'].join(''),'技术负责人');template.content.querySelectorAll('section').forEach(section=>{if(section.querySelector('h2')?.textContent.trim()==='教育背景')section.remove()});template.content.querySelectorAll('.doc-header p').forEach(paragraph=>{paragraph.textContent=paragraph.textContent.replace(' · 硕士（英国伯明翰大学）','')});template.content.querySelectorAll('li').forEach(item=>{if(item.textContent.includes('金科杯'))item.remove()});return template.innerHTML}
try{const savedWord=localStorage.getItem('yf-word97-resume');if(savedWord){const anonymousWord=anonymizeLegacyResume(savedWord);wordDoc.innerHTML=safeWordHtml(anonymousWord);if(anonymousWord!==savedWord)localStorage.setItem('yf-word97-resume',anonymousWord)}}catch{}
