// Calculator
let calcExpression='';
function solveExpression(expr){const nums=expr.split(/[+\-*/]/).map(Number),ops=expr.match(/[+\-*/]/g)||[];if(nums.some(Number.isNaN))return NaN;for(let i=0;i<ops.length;){if(ops[i]==='*'||ops[i]==='/'){const value=ops[i]==='*'?nums[i]*nums[i+1]:nums[i]/nums[i+1];nums.splice(i,2,value);ops.splice(i,1)}else i++}let out=nums[0];ops.forEach((op,i)=>out=op==='+'?out+nums[i+1]:out-nums[i+1]);return out}
function drawCalc(){ $('#calcDisplay').textContent=calcExpression||'0' }
$$('[data-calc]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.calc;if(v==='clear')calcExpression='';else if(v==='back')calcExpression=calcExpression.slice(0,-1);else if(v==='equals'){const n=solveExpression(calcExpression);calcExpression=Number.isFinite(n)?String(Math.round(n*1e10)/1e10):'Error'}else{if(calcExpression==='Error')calcExpression='';if(calcExpression.length<22)calcExpression+=v}drawCalc()}));

// Paint
const paintCanvas=$('#paintCanvas'),paintCtx=paintCanvas.getContext('2d');let paintColor='#000000',painting=false;
paintCtx.fillStyle='#fff';paintCtx.fillRect(0,0,paintCanvas.width,paintCanvas.height);paintCtx.lineCap='round';paintCtx.lineJoin='round';paintCtx.lineWidth=3;
function clearPaint(){paintCtx.fillStyle='#fff';paintCtx.fillRect(0,0,paintCanvas.width,paintCanvas.height)}
function invertPaint(){const image=paintCtx.getImageData(0,0,paintCanvas.width,paintCanvas.height),d=image.data;for(let i=0;i<d.length;i+=4){d[i]=255-d[i];d[i+1]=255-d[i+1];d[i+2]=255-d[i+2]}paintCtx.putImageData(image,0,0)}
function paintPoint(e){const r=paintCanvas.getBoundingClientRect();return{x:(e.clientX-r.left)*paintCanvas.width/r.width,y:(e.clientY-r.top)*paintCanvas.height/r.height}}
paintCanvas.addEventListener('pointerdown',e=>{painting=true;paintCanvas.setPointerCapture(e.pointerId);const p=paintPoint(e);paintCtx.beginPath();paintCtx.moveTo(p.x,p.y)});
paintCanvas.addEventListener('pointermove',e=>{if(!painting)return;const p=paintPoint(e);paintCtx.strokeStyle=paintColor;paintCtx.lineTo(p.x,p.y);paintCtx.stroke()});paintCanvas.addEventListener('pointerup',()=>painting=false);paintCanvas.addEventListener('pointercancel',()=>painting=false);
$$('[data-color]').forEach(b=>b.addEventListener('click',()=>{paintColor=b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('selected',x===b))}));
$('[data-paint-clear]').addEventListener('click',clearPaint);

// Minesweeper
let mineCells=[],mineTimer=null,mineSeconds=0,mineOver=false;
function nearby(index){const row=Math.floor(index/9),col=index%9;return mineCells.filter((_,i)=>{const r=Math.floor(i/9),c=i%9;return i!==index&&Math.abs(r-row)<=1&&Math.abs(c-col)<=1})}
function newMineGame(){clearInterval(mineTimer);mineTimer=null;mineSeconds=0;mineOver=false;$('#mineTime').textContent='000';$('#mineReset').textContent='☺';mineCells=Array.from({length:81},(_,i)=>({i,mine:false,revealed:false,flag:false}));let placed=0;while(placed<10){const i=Math.floor(Math.random()*81);if(!mineCells[i].mine){mineCells[i].mine=true;placed++}}mineCells.forEach(c=>c.count=nearby(c.i).filter(n=>n.mine).length);renderMines()}
function renderMines(){const grid=$('#mineGrid');grid.innerHTML='';mineCells.forEach(c=>{const b=document.createElement('button');b.dataset.index=c.i;b.setAttribute('aria-label',`方格 ${c.i+1}`);if(c.revealed){b.className='revealed'+(c.mine?' mine':'');b.textContent=c.mine?'✹':c.count||'';b.dataset.n=c.count}else if(c.flag)b.textContent='⚑';b.addEventListener('click',()=>revealMine(c.i));b.addEventListener('contextmenu',e=>{e.preventDefault();if(!c.revealed&&!mineOver){c.flag=!c.flag;renderMines()}});grid.appendChild(b)});$('#mineCount').textContent=String(Math.max(0,10-mineCells.filter(c=>c.flag).length)).padStart(3,'0')}
function revealMine(index){if(mineOver)return;const c=mineCells[index];if(c.revealed||c.flag)return;if(!mineTimer)mineTimer=setInterval(()=>{mineSeconds=Math.min(999,mineSeconds+1);$('#mineTime').textContent=String(mineSeconds).padStart(3,'0')},1000);c.revealed=true;if(c.mine){mineOver=true;mineCells.forEach(x=>{if(x.mine)x.revealed=true});$('#mineReset').textContent='☹';clearInterval(mineTimer)}else if(c.count===0)nearby(index).forEach(n=>{if(!n.revealed)revealMine(n.i)});if(mineCells.filter(x=>!x.mine&&x.revealed).length===71){mineOver=true;$('#mineReset').textContent='😎';clearInterval(mineTimer)}renderMines()}
$('#mineReset').addEventListener('click',newMineGame);newMineGame();

// Local Hack utilities. Inputs stay in the browser and are never transmitted.
const utf8Encoder=new TextEncoder(),utf8Decoder=new TextDecoder();
function bytesToBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=0x8000)binary+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(binary)}
function base64ToBytes(value){const normalized=value.replace(/\s/g,'').replace(/-/g,'+').replace(/_/g,'/'),padded=normalized+'='.repeat((4-normalized.length%4)%4),binary=atob(padded);return Uint8Array.from(binary,char=>char.charCodeAt(0))}
function bytesToHex(bytes){return[...bytes].map(byte=>byte.toString(16).padStart(2,'0')).join('')}
function formatToolError(error){return error instanceof URIError?'URL 编码格式无效':error?.message||'输入格式无效'}
$('#codecRun').addEventListener('click',()=>{const mode=$('#codecMode').value,input=$('#codecInput').value,output=$('#codecOutput');try{if(mode==='base64-encode')output.value=bytesToBase64(utf8Encoder.encode(input));else if(mode==='base64-decode')output.value=utf8Decoder.decode(base64ToBytes(input));else if(mode==='url-encode')output.value=encodeURIComponent(input);else if(mode==='url-decode')output.value=decodeURIComponent(input);else if(mode==='hex-encode')output.value=bytesToHex(utf8Encoder.encode(input));else{const compact=input.replace(/\s/g,'');if(!/^[0-9a-f]*$/i.test(compact)||compact.length%2)throw new Error('Hex 必须由偶数个十六进制字符组成');output.value=utf8Decoder.decode(Uint8Array.from(compact.match(/.{2}/g)||[],hex=>parseInt(hex,16)))}$('#codecStatus').textContent=`转换完成 · ${output.value.length} 个字符`}catch(error){output.value='';$('#codecStatus').textContent=formatToolError(error);playSystemSound('error')}});
$('#codecSwap').addEventListener('click',()=>{const input=$('#codecInput'),output=$('#codecOutput'),mode=$('#codecMode');[input.value,output.value]=[output.value,input.value];const inverse={'base64-encode':'base64-decode','base64-decode':'base64-encode','url-encode':'url-decode','url-decode':'url-encode','hex-encode':'hex-decode','hex-decode':'hex-encode'};mode.value=inverse[mode.value]});

async function digestHex(algorithm,value){return bytesToHex(new Uint8Array(await crypto.subtle.digest(algorithm,utf8Encoder.encode(value))))}
$('#hashRun').addEventListener('click',async()=>{const value=$('#hashInput').value,button=$('#hashRun');button.disabled=true;$('#hashStatus').textContent='正在计算...';try{const hashes=await Promise.all(['SHA-1','SHA-256','SHA-384','SHA-512'].map(name=>digestHex(name,value)));['hashSha1','hashSha256','hashSha384','hashSha512'].forEach((id,index)=>$('#'+id).value=hashes[index]);$('#hashStatus').textContent=`计算完成 · ${utf8Encoder.encode(value).length} 字节`}catch(error){$('#hashStatus').textContent=formatToolError(error);playSystemSound('error')}finally{button.disabled=false}});

function decodeJwtPart(part){const text=utf8Decoder.decode(base64ToBytes(part));return JSON.stringify(JSON.parse(text),null,2)}
$('#jwtRun').addEventListener('click',()=>{const parts=$('#jwtInput').value.trim().split('.');try{if(parts.length!==3)throw new Error('JWT 应包含 Header、Payload 和 Signature 三部分');$('#jwtHeader').value=decodeJwtPart(parts[0]);$('#jwtPayload').value=decodeJwtPart(parts[1]);const payload=JSON.parse(utf8Decoder.decode(base64ToBytes(parts[1]))),expiry=Number(payload.exp);$('#jwtStatus').textContent=expiry?`解码完成 · ${new Date(expiry*1000).toLocaleString('zh-CN')} ${expiry*1000<Date.now()?'已过期':'到期'}`:'解码完成 · 未声明过期时间'}catch(error){$('#jwtHeader').value='';$('#jwtPayload').value='';$('#jwtStatus').textContent=formatToolError(error);playSystemSound('error')}});

function parseIpv4(value){const octets=value.split('.');if(octets.length!==4||octets.some(part=>!/^\d{1,3}$/.test(part)||Number(part)>255))throw new Error('IPv4 地址格式无效');return octets.reduce((out,part)=>(out*256+Number(part))>>>0,0)}
function formatIpv4(value){return[value>>>24,value>>>16&255,value>>>8&255,value&255].join('.')}
$('#subnetRun').addEventListener('click',()=>{try{const [address,prefixText]= $('#subnetInput').value.trim().split('/'),prefix=Number(prefixText);if(!Number.isInteger(prefix)||prefix<0||prefix>32)throw new Error('CIDR 前缀必须在 0 到 32 之间');const ip=parseIpv4(address),mask=prefix===0?0:(0xffffffff<<(32-prefix))>>>0,network=(ip&mask)>>>0,broadcast=(network|(~mask>>>0))>>>0,total=2**(32-prefix);$('#subnetIp').textContent=formatIpv4(ip);$('#subnetMask').textContent=formatIpv4(mask);$('#subnetNetwork').textContent=`${formatIpv4(network)}/${prefix}`;$('#subnetBroadcast').textContent=formatIpv4(broadcast);$('#subnetHosts').textContent=prefix===32?formatIpv4(network):prefix===31?`${formatIpv4(network)} - ${formatIpv4(broadcast)}`:`${formatIpv4((network+1)>>>0)} - ${formatIpv4((broadcast-1)>>>0)}`;$('#subnetCount').textContent=`${total.toLocaleString('zh-CN')} 个地址 · ${Math.max(0,prefix>=31?total:total-2).toLocaleString('zh-CN')} 个可用主机`;$('#subnetStatus').textContent='计算完成'}catch(error){['subnetIp','subnetMask','subnetNetwork','subnetBroadcast','subnetHosts','subnetCount'].forEach(id=>$('#'+id).textContent='-');$('#subnetStatus').textContent=formatToolError(error);playSystemSound('error')}});
$('#subnetInput').addEventListener('keydown',event=>{if(event.key==='Enter')$('#subnetRun').click()});

function secureRandomIndex(limit){const ceiling=Math.floor(0x100000000/limit)*limit,buffer=new Uint32Array(1);do crypto.getRandomValues(buffer);while(buffer[0]>=ceiling);return buffer[0]%limit}
function generatePassword(){const groups=[];if($('#passwordUpper').checked)groups.push('ABCDEFGHJKLMNPQRSTUVWXYZ');if($('#passwordLower').checked)groups.push('abcdefghijkmnopqrstuvwxyz');if($('#passwordDigits').checked)groups.push('23456789');if($('#passwordSymbols').checked)groups.push('!@#$%^&*()-_=+[]{}?');const length=Math.max(8,Math.min(128,Number($('#passwordLength').value)||20));$('#passwordLength').value=length;if(!groups.length){$('#passwordStatus').textContent='请至少选择一种字符类型';playSystemSound('error');return}const all=groups.join(''),password=groups.map(group=>group[secureRandomIndex(group.length)]);while(password.length<length)password.push(all[secureRandomIndex(all.length)]);for(let i=password.length-1;i>0;i--){const j=secureRandomIndex(i+1);[password[i],password[j]]=[password[j],password[i]]}$('#passwordOutput').value=password.join('');const score=Math.min(100,Math.round(length*Math.log2(all.length)/1.28));$('#passwordMeter').style.width=`${score}%`;$('#passwordMeter').style.background=score<45?'#d34836':score<70?'#d6a21a':'#3c9b43';$('#passwordStatus').textContent=`约 ${Math.round(length*Math.log2(all.length))} 位熵`}
$('#passwordRun').addEventListener('click',generatePassword);

async function copyToolValue(id){const field=$('#'+id),value=field?.value||field?.textContent||'';if(!value)return;try{await navigator.clipboard.writeText(value)}catch{field.focus();field.select?.();document.execCommand('copy')}playSystemSound('notify')}
$$('[data-copy-target]').forEach(button=>button.addEventListener('click',()=>copyToolValue(button.dataset.copyTarget)));
$$('[data-clear-tool]').forEach(button=>button.addEventListener('click',()=>{const win=button.closest('.window');win.querySelectorAll('textarea,input[readonly]').forEach(field=>field.value='');win.querySelector('.statusbar span:first-child').textContent='就绪'}));

// Run and MS-DOS
const commandApps={notepad:'notepad',mspaint:'paint',paint:'paint',calc:'calculator',calculator:'calculator',winmine:'minesweeper',minesweeper:'minesweeper',sol:'solitaire',solitaire:'solitaire',pinball:'pinball',resume:'word',winword:'word',excel:'excel',powerpnt:'powerpoint',explorer:'computer',cmd:'dos',command:'dos',codec:'hack-codec',hash:'hack-hash',jwt:'hack-jwt',subnet:'hack-subnet',password:'hack-password'};
function runCommand(raw){const command=raw.trim().toLowerCase();if(command==='iexplore'||command==='iexplore.exe'){requestWebOpen(ieHome);return true}if(commandApps[command]){openApp(commandApps[command]);return true}if(command.startsWith('http://')||command.startsWith('https://')){requestWebOpen(command);return true}return false}
$('#runOk').addEventListener('click',()=>{const value=$('#runInput').value;if(runCommand(value)){closeWindow($('#window-run'));$('#runInput').value=''}else{showSystemDialog({title:'运行',message:`找不到文件“${value||'(空)'}”。\n请检查文件名是否正确，然后重试。`,type:'error'});$('#runInput').focus();$('#runInput').select()}});$('#runInput').addEventListener('keydown',e=>{if(e.key==='Enter')$('#runOk').click()});

// Power controls
$('#powerOk').addEventListener('click',()=>{const mode=$('input[name="power"]:checked').value;playSystemSound('shutdown');if(mode==='restart')setTimeout(()=>location.reload(),450);else{$('#shutdownScreen').classList.remove('hidden');$('#window-shutdown').classList.add('hidden')}});$('#powerOn').addEventListener('click',()=>location.reload());
